    #[test]
    fn c_function_fallthrough_analysis_checks_semantic_branches() {
        let filename = "semantic_function_branches.bcl";
        let ast_source = "function choose%(flag%)\nprint 1\nend function\nprint choose%(1)\nend\n";
        let semantic_source = "function choose%(flag%)\nif flag% = 1 then\nselect case flag%\ncase 1\nreturn 4\ncase else\nreturn 6\nend select\nelse\nreturn 5\nend if\nend function\nprint choose%(1)\nend\n";
        let parsed = parse_source(filename.to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let module = crate::semantic_ir::parse_and_adapt_named(filename, semantic_source).unwrap();
        assert!(
            c_semantic_callable_statements_by_source(&module, &program.functions[0]).is_some(),
            "semantic callable IF did not align with the compatibility body"
        );
        let resolved = resolver::resolve_with_semantic(program, Some(module)).unwrap();
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("return 4;")
                && output.contains("return 5;")
                && output.contains("return 6;"),
            "semantic IF/SELECT CASE branches were not emitted: {output}"
        );
        assert!(
            !output.contains("printf(\"1"),
            "AST callable body replaced typed branches: {output}"
        );

        let ast_source =
            "function choose%(flag%)\nprint 9\n\n\nreturn 1\nend function\nprint choose%(1)\nend\n";
        let semantic_source = "function choose%(flag%)\nwhile flag% = 1\nreturn 4\nwend\nreturn 5\nend function\nprint choose%(1)\nend\n";
        let parsed = parse_source(filename.to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let module = crate::semantic_ir::parse_and_adapt_named(filename, semantic_source).unwrap();
        assert!(
            c_semantic_callable_statements_by_source(&module, &program.functions[0]).is_some(),
            "semantic callable WHILE did not align"
        );
        let resolved = resolver::resolve_with_semantic(program, Some(module)).unwrap();
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("return 4;") && output.contains("return 5;"),
            "typed RETURN inside callable WHILE was not emitted: {output}"
        );
        assert!(
            !output.contains("printf(\"9"),
            "AST callable body replaced typed WHILE: {output}"
        );

        let ast_source =
            "function choose%(flag%)\nprint 9\n\n\nreturn 1\nend function\nprint choose%(1)\nend\n";
        let semantic_source = "function choose%(flag%)\nfor index% = 1 to 2\nreturn 4\nend for\nreturn 5\nend function\nprint choose%(1)\nend\n";
        let parsed = parse_source(filename.to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let module = crate::semantic_ir::parse_and_adapt_named(filename, semantic_source).unwrap();
        assert!(
            c_semantic_callable_statements_by_source(&module, &program.functions[0]).is_some(),
            "semantic callable FOR did not align"
        );
        let resolved = resolver::resolve_with_semantic(program, Some(module)).unwrap();
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("return 4;") && output.contains("return 5;"),
            "typed RETURN inside callable FOR was not emitted: {output}"
        );
        assert!(
            !output.contains("printf(\"9"),
            "AST callable body replaced typed FOR: {output}"
        );

        let ast_source = "function choose%(flag%)\nreturn 1\nend function\nprint choose%(1)\nend\n";
        let semantic_source = "function choose%(flag%)\nif flag% = 1 then\nreturn 4\nend if\nend function\nprint choose%(1)\nend\n";
        let parsed = parse_source(filename.to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let module = crate::semantic_ir::parse_and_adapt_named(filename, semantic_source).unwrap();
        let resolved = resolver::resolve_with_semantic(program, Some(module)).unwrap();
        let diagnostics = match generate(&resolved, Target::C) {
            Err(diagnostics) => diagnostics,
            Ok(_) => panic!("typed IF without ELSE unexpectedly passed C flow analysis"),
        };
        assert!(
            diagnostics.iter().any(|diagnostic| diagnostic
                .message
                .contains("return or terminate the process")),
            "typed IF fallthrough was not diagnosed: {diagnostics:?}"
        );
    }

