    #[test]
    fn c_semantic_numeric_expressions_dispatch_integer_and_bitwise_operators() {
        let source = "quotient& = 0\nremainder& = 0\nmask& = 0\ninverse& = 0\nrounded& = 0\nend\n";
        let parsed = parse_source("semantic_integer_ops.bcl".to_string(), source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "semantic_integer_ops.bcl",
                "quotient& = 9 \\ 2\nremainder& = 9 mod 2\nmask& = 5 and 3\ninverse& = not 5\nrounded& = 5.5 \\ 2\nend\n",
            ).unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(
            main.contains(
                "bv_l_quotient = ((int)((long)round((double)9) / (long)round((double)2)));"
            ),
            "semantic integer division missing: {main}"
        );
        assert!(
            main.contains(
                "bv_l_remainder = ((int)((long)round((double)9) % (long)round((double)2)));"
            ),
            "semantic MOD missing: {main}"
        );
        assert!(
            main.contains("bv_l_mask = ((int)((long)round((double)5) & (long)round((double)3)));"),
            "semantic bitwise AND missing: {main}"
        );
        assert!(
            main.contains("bv_l_inverse = ((int)(~(long)round((double)5)));"),
            "semantic NOT missing: {main}"
        );
        assert!(
            main.contains("round((double)5.5)"),
            "floating operand did not retain BASCAL rounding: {main}"
        );
        assert!(
            output.contains("#include <math.h>"),
            "integer conversion helper dependency missing: {output}"
        );
    }

