    #[test]
    fn c_semantic_swap_uses_typed_scalar_and_array_lvalues() {
        let ast_source = "a% = 1\nb% = 2\nc% = 3\nleft$ = \"left\"\nright$ = \"right\"\nother$ = \"other\"\ndim numbers%(3)\nnumbers%(0) = 4\nnumbers%(1) = 5\nnumbers%(2) = 6\ndim labels(3) as string\nlabels(0) = \"zero\"\nlabels(1) = \"one\"\nlabels(2) = \"two\"\nswap a%, b%\nswap left$, right$\nswap numbers%(0), numbers%(1)\nswap labels(0), labels(1)\nend\n";
        let semantic_source = "a% = 1\nb% = 2\nc% = 3\nleft$ = \"left\"\nright$ = \"right\"\nother$ = \"other\"\ndim numbers%(3)\nnumbers%(0) = 4\nnumbers%(1) = 5\nnumbers%(2) = 6\ndim labels(3) as string\nlabels(0) = \"zero\"\nlabels(1) = \"one\"\nlabels(2) = \"two\"\nswap a%, c%\nswap left$, other$\nswap numbers%(1), numbers%(2)\nswap labels(1), labels(2)\nend\n";
        let program = parse_source("semantic_swap.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named("semantic_swap.bcl", semantic_source)
                .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(
            main.contains("bt_swap_0 = bv_i_a;\n    bv_i_a = bv_i_c;\n    bv_i_c = bt_swap_0;"),
            "semantic numeric scalar SWAP missing: {main}"
        );
        assert!(main.contains("snprintf(bt_swap_1, sizeof(bt_swap_1), \"%s\", bv_s_left);\n    snprintf(bv_s_left, sizeof(bv_s_left), \"%s\", bv_s_other);"), "semantic string scalar SWAP missing: {main}");
        assert!(
            main.contains(
                "bt_swap_2 = bv_i_numbers[(1)];\n    bv_i_numbers[(1)] = bv_i_numbers[(2)];"
            ),
            "semantic numeric array SWAP missing: {main}"
        );
        assert!(main.contains("snprintf(bt_swap_3, sizeof(bt_swap_3), \"%s\", bv_s_labels[(1)]);\n    snprintf(bv_s_labels[(1)], sizeof(bv_s_labels[(1)]), \"%s\", bv_s_labels[(2)]);"), "semantic string array SWAP missing: {main}");
        assert!(
            !main.contains("bv_i_a = bv_i_b;"),
            "AST numeric SWAP replaced semantic IR: {main}"
        );
        assert!(
            !main.contains("bv_s_left, sizeof(bv_s_left), \"%s\", bv_s_right"),
            "AST string SWAP replaced semantic IR: {main}"
        );
    }

