    #[test]
    fn c_source_aligned_comment_dispatch_uses_typed_ir() {
        let ast_source = "print \"ast\"\n' AST comment\n\nend\n";
        let semantic_source = "print \"semantic\"\n' typed comment\n\nend\n";
        let parsed = parse_source("c_semantic_comment.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let resolved = resolver::resolve_with_semantic(
            program,
            Some(
                crate::semantic_ir::parse_and_adapt_named(
                    "c_semantic_comment.bcl",
                    semantic_source,
                )
                .unwrap(),
            ),
        )
        .unwrap();

        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(main.contains("// typed comment"), "typed comment missing: {main}");
        assert!(!main.contains("AST comment"), "AST comment replaced typed IR: {main}");
        assert!(main.contains("printf(\"semantic"), "typed PRINT missing: {main}");
        assert!(!main.contains("printf(\"ast"), "AST PRINT replaced typed IR: {main}");

        let ast_source = "procedure show()\nprint \"ast\"\n' AST callable comment\n\nend procedure\nshow()\nend\n";
        let semantic_source = "procedure show()\nprint \"semantic\"\n/* typed callable comment */\n\nend procedure\nshow()\nend\n";
        let parsed = parse_source("c_semantic_callable_comment.bcl".to_string(), ast_source)
            .unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let resolved = resolver::resolve_with_semantic(
            program,
            Some(
                crate::semantic_ir::parse_and_adapt_named(
                    "c_semantic_callable_comment.bcl",
                    semantic_source,
                )
                .unwrap(),
            ),
        )
        .unwrap();
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(output.contains("// typed callable comment"), "typed callable comment missing: {output}");
        assert!(!output.contains("AST callable comment"), "AST callable comment replaced typed IR: {output}");
        assert!(output.contains("printf(\"semantic"), "typed callable PRINT missing: {output}");
        assert!(!output.contains("printf(\"ast"), "AST callable PRINT replaced typed IR: {output}");
    }

