    #[test]
    fn c_nested_semantic_file_print_survives_recursive_loop_and_case_emitters() {
        let ast_source = "while false\nprint #1, \"ast while\"\nwend\nselect case 1\ncase 1\nprint #1, \"ast case\"\nend select\nend\n";
        let semantic_source = "while false\nprint #4, \"typed while\"\nwend\nselect case 1\ncase 1\nprint #4, \"typed case\"\nend select\nend\n";
        let parsed = parse_source(
            "c_nested_semantic_file_print_control_flow.bcl".to_string(),
            ast_source,
        )
        .expect("legacy source parses");
        let lower::Lowered { program, .. } = lower::lower(parsed).expect("legacy source lowers");
        let resolved = resolver::resolve_with_semantic(
            program,
            Some(
                crate::semantic_ir::parse_and_adapt_named(
                    "c_nested_semantic_file_print_control_flow.bcl",
                    semantic_source,
                )
                .expect("typed source parses"),
            ),
        )
        .expect("semantic nested file PRINT resolves");

        let output = generate(&resolved, Target::C).expect("C codegen succeeds").app;
        for payload in ["typed while", "typed case"] {
            assert!(
                output.contains(&format!("fprintf(bcc_files[3], \"{payload}\\n\");")),
                "typed nested {payload} PRINT missing: {output}"
            );
        }
        for payload in ["ast while", "ast case"] {
            assert!(
                !output.contains(&format!("fprintf(bcc_files[0], \"{payload}\\n\");")),
                "AST nested {payload} PRINT replaced typed IR: {output}"
            );
        }
    }

