    #[test]
    fn c_generation_dispatches_typed_console_input_from_semantic_ir() {
        let parsed = parse_source(
            "semantic_input.bcl".to_string(),
            "input \"ast\"; value%\nend\n",
        )
        .unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "semantic_input.bcl",
                "input \"semantic\"; value%\nend\n",
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(
            main.contains("printf(\"semantic? \");"),
            "semantic INPUT prompt missing: {main}"
        );
        assert!(
            main.contains("bv_i_value = atoi(bcc_input_buf);"),
            "typed semantic INPUT conversion missing: {main}"
        );
        assert!(
            !main.contains("printf(\"ast? \");"),
            "AST INPUT prompt replaced semantic IR: {main}"
        );
    }

