    #[test]
    fn c_generation_dispatches_typed_rank_two_array_reads_and_writes() {
        let ast_source = "dim values%(2, 3)\ndim labels(2, 3) as string\nvalues%(1, 1) = 2\nvalues%(1, 1) += 3\nlabels(1, 1) = \"old\"\ninput \"old prompt\"; values%(1, 1)\nprint values%(1, 1), labels(1, 1)\nend\n";
        let parsed =
            parse_source("c_semantic_rank_two_arrays.bcl".to_string(), ast_source).unwrap();
        let crate::lower::Lowered { program, .. } = crate::lower::lower(parsed).unwrap();
        let mut resolved = crate::resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(crate::semantic_ir::parse_and_adapt_named(
            "c_semantic_rank_two_arrays.bcl",
            "dim values%(2, 3)\ndim labels(2, 3) as string\nvalues%(2, 3) = 7\nvalues%(2, 3) += 11\nlabels(2, 3) = \"semantic\"\ninput \"semantic prompt\"; values%(2, 3)\nprint values%(2, 3), labels(2, 3)\nend\n",
        ).unwrap());
        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(
            main.contains("bv_i_values[(2)][(3)] = 7;"),
            "semantic rank-two numeric assignment missing: {main}"
        );
        assert!(
            main.contains("bv_i_values[(2)][(3)] = (bv_i_values[(2)][(3)] + 11);"),
            "semantic rank-two compound assignment missing: {main}"
        );
        assert!(
            main.contains("printf(\"semantic prompt? \"")
                && main.contains("bv_i_values[(2)][(3)] = atoi(bcc_input_buf);"),
            "semantic rank-two INPUT target missing: {main}"
        );
        assert!(main.contains("snprintf(bv_s_labels[(2)][(3)], sizeof(bv_s_labels[(2)][(3)]), \"%s\", \"semantic\");"), "semantic rank-two string assignment missing: {main}");
        assert!(
            main.contains("bv_i_values[(2)][(3)]"),
            "semantic rank-two numeric read missing: {main}"
        );
        assert!(
            main.contains("bv_s_labels[(2)][(3)]"),
            "semantic rank-two string read missing: {main}"
        );
        assert!(
            !main.contains("\"old\""),
            "AST rank-two array value replaced semantic IR: {main}"
        );
        assert!(
            !main.contains("[(1)]"),
            "AST rank-two array indices replaced semantic IR: {main}"
        );
    }

