    #[test]
    fn c64_float_operation_checks_follow_semantic_expressions() {
        let ast = parse_source(
            "c64_semantic_float_expression.bcl".to_string(),
            "value% = 1\nend\n",
        )
        .unwrap();
        let crate::lower::Lowered { program, .. } = crate::lower::lower(ast).unwrap();
        let mut resolved = crate::resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c64_semantic_float_expression.bcl",
                "value% = 1.5\nend\n",
            )
            .unwrap(),
        );
        let diagnostics = match generate(&resolved, Target::C64) {
            Err(diagnostics) => diagnostics,
            Ok(_) => panic!("typed floating literal must be rejected"),
        }
        .into_iter()
        .map(|diagnostic| diagnostic.message)
        .collect::<Vec<_>>();
        assert!(diagnostics
            .iter()
            .any(|message| message.contains("floating-point literals")));

        let ast = parse_source(
            "c64_semantic_integer_expression.bcl".to_string(),
            "value% = 1.5\nend\n",
        )
        .unwrap();
        let crate::lower::Lowered { program, .. } = crate::lower::lower(ast).unwrap();
        let mut resolved = crate::resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c64_semantic_integer_expression.bcl",
                "value% = 1\nend\n",
            )
            .unwrap(),
        );
        assert!(
            generate(&resolved, Target::C64).is_ok(),
            "stale AST-only floating literal must not reject semantic integer IR"
        );

        let ast =
            parse_source("c64_semantic_division.bcl".to_string(), "value% = 4\nend\n").unwrap();
        let crate::lower::Lowered { program, .. } = crate::lower::lower(ast).unwrap();
        let mut resolved = crate::resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c64_semantic_division.bcl",
                "value% = 4 / 2\nend\n",
            )
            .unwrap(),
        );
        let diagnostics = match generate(&resolved, Target::C64) {
            Err(diagnostics) => diagnostics,
            Ok(_) => panic!("typed true division must be rejected"),
        };
        assert!(diagnostics
            .iter()
            .any(|diagnostic| diagnostic.message.contains("true division")));

        let ast = parse_source(
            "c64_semantic_integer_division.bcl".to_string(),
            "value% = 4 / 2\nend\n",
        )
        .unwrap();
        let crate::lower::Lowered { program, .. } = crate::lower::lower(ast).unwrap();
        let mut resolved = crate::resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c64_semantic_integer_division.bcl",
                "value% = 4\\2\nend\n",
            )
            .unwrap(),
        );
        assert!(
            generate(&resolved, Target::C64).is_ok(),
            "stale AST-only true division must not reject semantic integer division"
        );
    }

