    #[test]
    fn c_dispatches_typed_discarded_expressions_in_module_blocks_and_callables() {
        let ast_source = "function value%()\nreturn 1\nend function\nprocedure notify()\nprint 97\nend procedure\nprocedure run()\nif true then\nnotify()\nprint 98\nend if\nend procedure\nif true then\nprint 96\nend if\nprint 99\nrun()\nend\n";
        let semantic_source = "function value%()\nreturn 2\nend function\nprocedure notify()\nprint 7\nend procedure\nprocedure run()\nif true then\nnotify()\nvalue%() + 3\nend if\nend procedure\nif true then\nnotify()\nend if\nvalue%() + 4\nrun()\nend\n";
        let parsed = parse_source(
            "c_discarded_typed_expression.bcl".to_string(),
            ast_source,
        )
        .unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let resolved = resolver::resolve_with_semantic(
            program,
            Some(
                crate::semantic_ir::parse_and_adapt_named(
                    "c_discarded_typed_expression.bcl",
                    semantic_source,
                )
                .unwrap(),
            ),
        )
        .unwrap();

        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(main.contains("(void)("), "typed expression missing: {main}");
        assert!(main.contains("bf_i_value()"), "typed callable missing: {main}");
        assert!(main.contains("bf_i_notify();"), "typed nested procedure call missing: {main}");
        assert!(main.contains("+ 4"), "typed module operand missing: {main}");
        assert!(!main.contains("99"), "AST PRINT replaced typed expression: {main}");
        assert!(!main.contains("96"), "AST PRINT replaced typed nested call: {main}");
        let run = output
            .split("bf_i_run(void) {")
            .nth(1)
            .unwrap_or_else(|| panic!("generated procedure missing: {output}"))
            .split("\n}")
            .next()
            .unwrap();
        assert!(run.contains("+ 3"), "typed nested expression missing: {run}");
        assert!(run.contains("bf_i_notify();"), "typed nested procedure call missing: {run}");
        assert!(!run.contains("98"), "AST block replaced typed expression: {run}");
    }

