    #[test]
    fn c_semantic_numeric_builtin_call_uses_typed_argument() {
        let program = parse_source(
            "semantic_abs.bcl".to_string(),
            "value% = 1\nrounded% = 1\nfixed% = 1\nsquare! = 1.0\nsign% = 1\nnearest% = 1\nwide% = 1\nsingle! = 1.0\ndouble# = 1.0\nsine! = 1.0\ncosine! = 1.0\ntangent! = 1.0\nangle! = 1.0\nlogarithm! = 1.0\nexponential! = 1.0\nend\n",
        )
        .unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "semantic_abs.bcl",
                "value% = abs(-9)\nrounded% = int(-3.7)\nfixed% = fix(-3.7)\nsquare! = sqr(9)\nsign% = sgn(-9)\nnearest% = cint(-3.7)\nwide% = clng(3.7)\nsingle! = csng(2)\ndouble# = cdbl(2)\nsine! = sin(0)\ncosine! = cos(0)\ntangent! = tan(0)\nangle! = atn(0)\nlogarithm! = log(1)\nexponential! = exp(0)\nend\n",
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(
            main.contains("(int)(fabs((double)(-(9))))"),
            "semantic ABS argument wasn't emitted: {main}"
        );
        assert!(
            main.contains("floor((double)(-(3.7)))"),
            "semantic INT argument wasn't emitted: {main}"
        );
        assert!(
            main.contains("trunc((double)(-(3.7)))"),
            "semantic FIX argument wasn't emitted: {main}"
        );
        assert!(
            main.contains("sqrt((double)(9))"),
            "semantic SQR argument wasn't emitted: {main}"
        );
        assert!(
            main.contains("bcc_sgn((double)(-(9)))"),
            "semantic SGN argument wasn't emitted: {main}"
        );
        assert!(
            main.contains("((int)round((double)(-(3.7))))"),
            "semantic CINT argument wasn't emitted: {main}"
        );
        assert!(
            main.contains("((int)round((double)(3.7)))"),
            "semantic CLNG argument wasn't emitted: {main}"
        );
        assert!(
            main.contains("((float)(2))"),
            "semantic CSNG argument wasn't emitted: {main}"
        );
        assert!(
            main.contains("((double)(2))"),
            "semantic CDBL argument wasn't emitted: {main}"
        );
        for (function, argument) in [
            ("sin", "0"),
            ("cos", "0"),
            ("tan", "0"),
            ("atan", "0"),
            ("log", "1"),
            ("exp", "0"),
        ] {
            assert!(
                main.contains(&format!("{function}((double)({argument}))")),
                "semantic {function} argument wasn't emitted: {main}"
            );
        }
        assert!(
            !main.contains("bv_i_value = 1;"),
            "AST assignment replaced semantic ABS: {main}"
        );
    }

    #[test]
    fn c_semantic_numeric_user_function_calls_use_resolved_signatures() {
        let ast_source = "function add%(left%, right% = 3)\nreturn left% + right%\nend function\nfunction double%(value%)\nreturn value% * 2\nend function\nfunction bump%(byref value%)\nvalue% = value% + 1\nreturn value%\nend function\nresult% = double%(add%(1, 2))\ndefaultResult% = add%(1)\nold% = 1\nnew% = 2\nchanged% = bump%(old%)\nprint double%(add%(1, 2))\nend\n";
        let semantic_source = "function add%(left%, right% = 8)\nreturn left% + right%\nend function\nfunction double%(value%)\nreturn value% * 2\nend function\nfunction bump%(byref value%)\nvalue% = value% + 1\nreturn value%\nend function\nresult% = double%(add%(3, 4))\ndefaultResult% = add%(9)\nold% = 1\nnew% = 2\nchanged% = bump%(new%)\nprint double%(add%(5, 6))\nend\n";
        let program = parse_source("semantic_user_calls.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named("semantic_user_calls.bcl", semantic_source)
                .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(
            main.contains("(3, 4)"),
            "semantic nested call arguments missing: {main}"
        );
        assert!(
            main.contains("(5, 6)"),
            "semantic PRINT call arguments missing: {main}"
        );
        assert!(
            main.contains("(9, 8)"),
            "semantic function default argument missing: {main}"
        );
        assert!(
            !main.contains("(9, 3)"),
            "AST function default argument replaced semantic IR: {main}"
        );
        assert!(
            main.contains("bf_i_bump(&bv_i_new)"),
            "semantic BYREF lvalue missing: {main}"
        );
        assert!(
            !main.contains("bf_i_bump(&bv_i_old)"),
            "AST BYREF lvalue replaced semantic IR: {main}"
        );
        assert!(
            !main.contains("(1, 2)"),
            "AST nested call arguments replaced semantic IR: {main}"
        );
        assert!(
            main.contains("bv_i_result = "),
            "semantic call assignment was not emitted: {main}"
        );
    }

    #[test]
    fn c_semantic_string_user_function_calls_use_resolved_signatures() {
        let ast_source = "function join$(left$, right$ = \"!\")\nreturn left$ + right$\nend function\nresult$ = join$(\"old\")\nprint join$(\"old\", \"?\")\nend\n";
        let semantic_source = "function join$(left$, right$ = \"?\")\nreturn left$ + right$\nend function\nresult$ = join$(\"new\")\nprint join$(\"new\", \".\")\nend\n";
        let program =
            parse_source("semantic_string_user_calls.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "semantic_string_user_calls.bcl",
                semantic_source,
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        let main = output.rsplit_once("int main(").expect("generated main").1;
        assert!(
            main.contains("bf_s_join(\"new\", \"?\", bt_s_"),
            "semantic default string argument missing: {main}"
        );
        assert!(
            !main.contains("bf_s_join(\"new\", \"!\", bt_s_"),
            "AST default string argument replaced semantic IR: {main}"
        );
        assert!(
            main.contains("bf_s_join(\"new\", \".\", bt_s_"),
            "semantic PRINT call arguments missing: {main}"
        );
        assert!(
            !main.contains("\"old\""),
            "AST string arguments replaced semantic IR: {main}"
        );
        assert!(
            main.contains("snprintf(bv_s_result"),
            "semantic string call assignment was not emitted: {main}"
        );
    }

    #[test]
    fn c_semantic_mid_assign_uses_typed_operands() {
        let ast_source = "function identity$(value$)\nreturn value$\nend function\ntext$ = \"abcdef\"\nmid$(text$, 2, 2) = identity$(\"old\")\nend\n";
        let semantic_source = "function identity$(value$)\nreturn value$\nend function\ntext$ = \"abcdef\"\nmid$(text$, 3, 2) = identity$(\"new\")\nend\n";
        let program = parse_source("semantic_mid_assign.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named("semantic_mid_assign.bcl", semantic_source)
                .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("bf_s_identity(\"new\", bt_s_"),
            "semantic MID$ string call missing: {output}"
        );
        assert!(
            output.contains("bcc_mid_assign(bv_s_text, (3), (2), bt_s_"),
            "semantic MID$ operands missing: {output}"
        );
        assert!(
            !output.contains("identity(\"old\")"),
            "AST MID$ value replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("bcc_mid_assign(bv_s_text, (2)"),
            "AST MID$ index replaced semantic IR: {output}"
        );
    }

