    #[test]
    fn c_callable_array_declarations_use_the_matched_semantic_body() {
        let ast_source = "function f%()\ndim values%(10)\nreturn 0\nend function\nend\n";
        let program = parse_source(
            "semantic_callable_array_authority.bcl".to_string(),
            ast_source,
        )
        .unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let function = &program.functions[0];

        let omitted_semantic_dim = crate::semantic_ir::parse_and_adapt_named(
            "semantic_callable_array_authority.bcl",
            "function f%()\nreturn 0\nend function\nend\n",
        )
        .unwrap();
        let arrays = collect_callable_array_declarations(
            function,
            Some(&omitted_semantic_dim),
            None,
            &HashMap::new(),
        )
        .unwrap();
        assert!(
            arrays.is_empty(),
            "AST local DIM leaked into semantic table"
        );

        let semantic_dim = crate::semantic_ir::parse_and_adapt_named(
            "semantic_callable_array_authority.bcl",
            "function f%()\ndim values%(5)\nreturn 0\nend function\nend\n",
        )
        .unwrap();
        let arrays = collect_callable_array_declarations(
            function,
            Some(&semantic_dim),
            None,
            &HashMap::new(),
        )
        .unwrap();
        assert_eq!(
            arrays.get("bv_i_values").map(|info| info.bounds.as_slice()),
            Some(&[5][..])
        );

        let unmatched_semantic_callable = crate::semantic_ir::parse_and_adapt_named(
            "semantic_callable_array_authority.bcl",
            "function other%()\nreturn 0\nend function\nend\n",
        )
        .unwrap();
        let arrays = collect_callable_array_declarations(
            function,
            Some(&unmatched_semantic_callable),
            None,
            &HashMap::new(),
        )
        .unwrap();
        assert_eq!(
            arrays.get("bv_i_values").map(|info| info.bounds.as_slice()),
            Some(&[10][..])
        );
    }

