    #[test]
    fn c_generation_dispatches_all_semantic_numeric_packs_in_lset() {
        for (builtin, c_function, width) in [
            ("mkl$", "bcc_mkl", 4),
            ("mks$", "bcc_mks", 4),
            ("mkd$", "bcc_mkd", 8),
        ]
        .into_iter()
        {
            let filename = format!("semantic_lset_{builtin}.bcl");
            let ast_source = format!(
                "open \"record.dat\" for random as #1 len = {width}\nfield #1, {width} as buffer$\nlset buffer$ = {builtin}(1)\nend\n"
            );
            let semantic_source = format!(
                "open \"record.dat\" for random as #1 len = {width}\nfield #1, {width} as buffer$\nlset buffer$ = {builtin}(2)\nend\n"
            );
            let parsed = parse_source(filename.clone(), &ast_source).unwrap();
            let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
            let resolved = resolver::resolve_with_semantic(
                program,
                Some(
                    crate::semantic_ir::parse_and_adapt_named(&filename, &semantic_source).unwrap(),
                ),
            )
            .unwrap();

            let output = generate(&resolved, Target::C).unwrap().app;
            let semantic_call = output
                .lines()
                .find(|line| line.contains(&format!("{c_function}(bv_s_buffer,")))
                .unwrap_or_else(|| panic!("missing typed {builtin} pack in:\n{output}"));

            assert!(semantic_call.contains("2);"), "{semantic_call}");
            assert!(!semantic_call.contains("1);"), "{semantic_call}");
            assert!(
                !output.contains(&format!("{c_function}(bv_s_buffer, 1);")),
                "{output}"
            );
        }
    }

