    #[test]
    fn c_callable_generation_dispatches_source_aligned_semantic_assignments_and_prints() {
        let ast_source =
            "function f%()\nx% = 1\nprint x%\nreturn x%\nend function\nprint f%()\nend\n";
        let semantic_source =
            "function f%()\nx% = 9\nprint 17\nreturn 23\nend function\nprint f%()\nend\n";
        let program = parse_source("c_callable_semantic.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named("c_callable_semantic.bcl", semantic_source)
                .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains(" = 9;"),
            "semantic callable assignment missing: {output}"
        );
        assert!(
            !output.contains(" = 1;"),
            "AST callable assignment replaced semantic IR: {output}"
        );
        assert!(
            output.contains("printf(\"%d\\n\", 17);"),
            "semantic callable PRINT missing: {output}"
        );
        assert!(
            !output.contains("printf(\"%d\\n\", bv_i_x);"),
            "AST callable PRINT replaced semantic IR: {output}"
        );
        assert!(
            output.contains("return 23;"),
            "semantic callable RETURN missing: {output}"
        );
    }

