    #[test]
    fn c_callable_generation_dispatches_semantic_local_array_access() {
        let ast_source = "function f%()\ndim values%(10)\ndim grid%(2, 3)\nvalues%(1) = 2\nvalues%(1) += 3\ngrid%(1, 1) = 4\nprint values%(1), grid%(1, 1)\nreturn 0\nend function\nprint f%()\nend\n";
        let semantic_source = "function f%()\ndim values%(10)\ndim grid%(2, 3)\nvalues%(2) = 7\nvalues%(2) += 11\ngrid%(2, 3) = 19\nprint values%(2), grid%(2, 3)\nreturn 0\nend function\nprint f%()\nend\n";
        let program =
            parse_source("c_callable_semantic_array.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c_callable_semantic_array.bcl",
                semantic_source,
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("bv_i_values[(2)] = 7;"),
            "semantic callable array write missing: {output}"
        );
        assert!(
            output.contains("bv_i_values[(2)] = (bv_i_values[(2)] + 11);"),
            "semantic callable compound array assignment missing: {output}"
        );
        assert!(
            output.contains("bv_i_grid[(2)][(3)] = 19;"),
            "semantic callable rank-two array assignment missing: {output}"
        );
        assert!(
            output.contains("bv_i_grid[(2)][(3)]"),
            "semantic callable rank-two array read missing: {output}"
        );
        assert!(
            output.contains("bv_i_values[(2)], bv_i_grid[(2)][(3)]"),
            "semantic callable array reads missing: {output}"
        );
        assert!(
            !output.contains("bv_i_values[(1)] = 2;"),
            "AST callable array write replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("bv_i_values[(1)] += 3;"),
            "AST callable compound array assignment replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("printf(\"%d\\n\", bv_i_values[(1)]);"),
            "AST callable array read replaced semantic IR: {output}"
        );
    }

