        let semantic_source = "function identity$(value$)\nreturn value$\nend function\nfunction f%()\ntext$ = \"abcdef\"\nmid$(text$, 3, 2) = identity$(\"SEM\")\nreturn 0\nend function\nprint f%()\nend\n";
