    #[test]
    fn c_semantic_for_bounds_transpile_typed_scalar_method_calls() {
        let ast_source = "method adjust%[integer](delta%)\nreturn self%+delta%\nend method\nvalue%=10\ndim index%\nfor index%=0 to 1 step 1\nprint index%\nend for\nfunction runner%()\ndim local%\nfor local%=0 to 1 step 1\nprint local%\nend for\nreturn 0\nend function\nrunner%()\nend\n";
        let semantic_source = "method adjust%[integer](delta%)\nreturn self%+delta%\nend method\nvalue%=20\ndim index%\nfor index%=value%.adjust(1) to value%.adjust(2) step value%.adjust(0)\nprint index%\nend for\nfunction runner%()\ndim local%\nfor local%=value%.adjust(3) to value%.adjust(4) step value%.adjust(0)\nprint local%\nend for\nreturn 0\nend function\nrunner%()\nend\n";
        let parsed =
            parse_source("c_semantic_method_for_bounds.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c_semantic_method_for_bounds.bcl",
                semantic_source,
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("for (bv_i_index = bt_start_1;"),
            "typed method call wasn't emitted as FOR start: {output}"
        );
        assert!(
            output.contains("bt_lim_1 = bf_i_adjust_i(bv_i_value, 2);"),
            "typed method call wasn't emitted as FOR limit: {output}"
        );
        assert!(
            output.contains("bt_step_1 = bf_i_adjust_i(bv_i_value, 0);"),
            "typed method call wasn't emitted as FOR step: {output}"
        );
        let start = output
            .find("bt_start_1 = bf_i_adjust_i(bv_i_value, 1);")
            .expect("staged FOR start");
        let limit = output
            .find("bt_lim_1 = bf_i_adjust_i(bv_i_value, 2);")
            .expect("staged FOR limit");
        let step = output
            .find("bt_step_1 = bf_i_adjust_i(bv_i_value, 0);")
            .expect("staged FOR step");
        assert!(
            start < limit && limit < step,
            "FOR operands reordered: {output}"
        );
        let callable = output
            .split("int bf_i_runner(void) {")
            .nth(1)
            .expect("generated runner callable")
            .split("\n}")
            .next()
            .expect("runner body");
        assert!(
            callable.contains("bf_i_adjust_i(bv_i_value, 3)")
                && callable.contains("bf_i_adjust_i(bv_i_value, 4)")
                && callable.contains("bf_i_adjust_i(bv_i_value, 0)"),
            "typed method calls weren't emitted in callable FOR bounds: {callable}"
        );
        assert!(
            !output.contains("for (bv_i_index = 0;"),
            "AST FOR start leaked: {output}"
        );
        assert!(
            !callable.contains("for (bv_i_local = 0;"),
            "AST callable FOR start leaked: {callable}"
        );
    }

    #[test]
    fn c_semantic_for_snapshots_variable_start_before_side_effectful_bounds() {
        let ast_source = "method update%[integer](byref target%)\ntarget%=target%+1\nreturn self%+target%\nend method\nindex%=5\nfor index%=index% to index%.update(index%)\nprint index%\nend for\nend\n";
        let semantic_source = "method update%[integer](byref target%)\ntarget%=target%+1\nreturn self%+target%\nend method\nindex%=5\nfor index%=index% to index%.update(index%)\nprint index%\nend for\nend\n";
        let parsed =
            parse_source("c_semantic_for_start_snapshot.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c_semantic_for_start_snapshot.bcl",
                semantic_source,
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        let start = output
            .find("bt_start_0 = bv_i_index;")
            .or_else(|| output.find("bt_start_1 = bv_i_index;"))
            .unwrap_or_else(|| panic!("FOR start snapshot missing: {output}"));
        let limit = output
            .find("bf_i_update_i(bv_i_index, &bv_i_index)")
            .unwrap_or_else(|| panic!("side-effecting FOR limit missing: {output}"));
        assert!(
            start < limit,
            "FOR start was read after its bound mutated it: {output}"
        );
        assert!(
            output.contains("for (bv_i_index = bt_start_0;"),
            "FOR header did not use its captured start: {output}"
        );
    }

