    #[test]
    fn c_error_runtime_state_uses_semantic_control_statements() {
        let source = "print 1\nend\n";
        let parsed = parse_source("semantic_error_state.bcl".to_string(), source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let mut resolved = resolver::resolve_with_semantic(
            program,
            Some(
                crate::semantic_ir::parse_and_adapt_named("semantic_error_state.bcl", source)
                    .unwrap(),
            ),
        )
        .unwrap();

        // A stale AST TRY at a source position represented by a semantic
        // PRINT must not cause C to allocate error-runtime globals.
        let stale_try = parse_source(
            "semantic_error_state.bcl".to_string(),
            "try\nprint 1\ncatch e%, l%\nprint 2\nend try\n",
        )
        .unwrap();
        resolved.program.statements[0].kind = stale_try.statements[0].kind.clone();

        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            !output.contains("static int bcc_on_error_target"),
            "stale AST TRY caused semantic C error-runtime state to be emitted: {output}"
        );
    }

    #[test]
