    #[test]
    fn c_generation_dispatches_semantic_sequential_open_modes() {
        let ast_source = "program OpenSemantic\nprocedure writer()\nopen \"ast-call.dat\" for output as #2\nend procedure\nwriter()\nopen \"ast-main.dat\" for append as #3\nopen \"ast-input.dat\" for input as #4\nopen \"ast-random.dat\" for random as #5\nend\n";
        let semantic_source = "program OpenSemantic\nprocedure writer()\nopen \"semantic-call.dat\" for output as #2\nend procedure\nwriter()\nopen \"semantic-main.dat\" for append as #3\nopen \"semantic-input.dat\" for input as #4\nopen \"semantic-random.dat\" for random as #5\nend\n";
        let program = parse_source("c_semantic_open.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named("c_semantic_open.bcl", semantic_source)
                .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("fopen(\"semantic-call.dat\", \"w\")"),
            "semantic callable OUTPUT path missing: {output}"
        );
        assert!(
            output.contains("fopen(\"semantic-main.dat\", \"a\")"),
            "semantic top-level APPEND path missing: {output}"
        );
        assert!(
            output.contains("fopen(\"semantic-input.dat\", \"r\")"),
            "semantic top-level INPUT path missing: {output}"
        );
        assert!(
            output.contains("fopen(\"semantic-random.dat\", \"rb+\")"),
            "semantic top-level RANDOM path missing: {output}"
        );
        assert!(
            output.contains("fopen(\"semantic-random.dat\", \"wb+\")"),
            "semantic top-level RANDOM create fallback missing: {output}"
        );
        assert!(
            output.contains("bcc_err = 53;"),
            "semantic INPUT error code missing: {output}"
        );
        assert!(
            output.contains("bcc_err = 75;"),
            "semantic RANDOM error code missing: {output}"
        );
        assert!(
            !output.contains("ast-call.dat"),
            "AST callable OPEN path replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("ast-main.dat"),
            "AST top-level OPEN path replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("ast-input.dat"),
            "AST INPUT path replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("ast-random.dat"),
            "AST RANDOM path replaced semantic IR: {output}"
        );
        assert!(
            output.contains("static FILE* bcc_files[BCC_MAX_CHANNELS];"),
            "semantic OPEN did not register channel storage: {output}"
        );
    }

