    #[test]
    fn c_generation_dispatches_semantic_seek_positions() {
        let ast_source = "program SeekSemantic\nprocedure skipRecord()\nseek #1, 4\nend procedure\nopen \"records.dat\" for random as #1 len = 4\nfield #1, 4 as record$\nseek #1, 2\nskipRecord()\nend\n";
        let semantic_source = "program SeekSemantic\nprocedure skipRecord()\nseek #1, 5\nend procedure\nopen \"records.dat\" for random as #1 len = 4\nfield #1, 4 as record$\nseek #1, 3\nskipRecord()\nend\n";
        let program = parse_source("c_semantic_seek.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named("c_semantic_seek.bcl", semantic_source)
                .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("fseek(bcc_files[0], ((long)(3) - 1L) * 4L, SEEK_SET);"),
            "semantic top-level record position missing: {output}"
        );
        assert!(
            output.contains("fseek(bcc_files[0], ((long)(5) - 1L) * 4L, SEEK_SET);"),
            "semantic callable record position missing: {output}"
        );
        assert!(
            !output.contains("((long)(2) - 1L)"),
            "AST top-level position replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("((long)(4) - 1L)"),
            "AST callable position replaced semantic IR: {output}"
        );
    }

    #[test]
    fn c_generation_dispatches_semantic_raw_field_get_put() {
        let ast_source = "program RawGetPut\nprocedure fetch()\nget #1, 4\nend procedure\nopen \"records.dat\" for random as #1 len = 4\nfield #1, 4 as buffer$\nget #1, 2\nput #1, 3\nfetch()\nend\n";
        let semantic_source = "program RawGetPut\nprocedure fetch()\nget #1, 7\nend procedure\nopen \"records.dat\" for random as #1 len = 4\nfield #1, 4 as buffer$\nget #1, 5\nput #1, 6\nfetch()\nend\n";
        let program = parse_source("c_semantic_raw_get_put.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c_semantic_raw_get_put.bcl",
                semantic_source,
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("bcc_get_record_fields_1_0(bcc_files[0], 5, bv_s_buffer)"),
            "semantic top-level GET missing: {output}"
        );
        assert!(
            output.contains("bcc_put_record_fields_1_0(bcc_files[0], 6, bv_s_buffer)"),
            "semantic top-level PUT missing: {output}"
        );
        assert!(
            output.contains("bcc_get_record_fields_1_0(bcc_files[0], 7, bv_s_buffer)"),
            "semantic callable GET missing: {output}"
        );
        assert!(
            !output.contains("bcc_get_record_fields_1_0(bcc_files[0], 2,"),
            "AST top-level GET position replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("bcc_put_record_fields_1_0(bcc_files[0], 3,"),
            "AST top-level PUT position replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("bcc_get_record_fields_1_0(bcc_files[0], 4,"),
            "AST callable GET position replaced semantic IR: {output}"
        );
    }

    #[test]
    fn c_generation_dispatches_semantic_raw_field_layout() {
        let ast_source = "program FieldSource\nprocedure fetch()\nget #1, 1\nend procedure\nopen \"records.dat\" for random as #1 len = 4\nfield #1, 4 as astbuf$\nget #1, 1\nend\n";
        let semantic_source = "program FieldSource\nprocedure fetch()\nget #1, 1\nend procedure\nopen \"records.dat\" for random as #1 len = 6\nfield #1, 6 as semanticbuf$\nget #1, 1\nend\n";
        let program = parse_source("c_semantic_field_layout.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c_semantic_field_layout.bcl",
                semantic_source,
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("char bv_s_semanticbuf[256]"),
            "semantic FIELD variable was not declared: {output}"
        );
        assert!(
            !output.contains("char bv_s_astbuf[256]"),
            "stale AST FIELD binding was declared: {output}"
        );
        assert!(
            output.contains("bcc_get_record_fields_1_0(bcc_files[0], 1, bv_s_semanticbuf)"),
            "semantic FIELD binding did not feed GET: {output}"
        );
        assert_eq!(
            output
                .matches("bcc_get_record_fields_1_0(bcc_files[0], 1, bv_s_semanticbuf)")
                .count(),
            2,
            "both the callable prepass and top-level emission must use semantic FIELD bindings: {output}"
        );
        assert!(
            output.contains("unsigned char buffer[6];"),
            "semantic FIELD width missing from generated record helper: {output}"
        );
        assert!(
            !output.contains("bcc_get_record_fields_1_0(bcc_files[0], 1, bv_s_astbuf)"),
            "AST FIELD binding replaced semantic IR: {output}"
        );
    }

