    #[test]
    fn c_record_file_write_consumes_semantic_literal_values() {
        let ast_source = "program SemanticRecordWrite\nfunction amount%(input%)\nreturn input%\nend function\nfunction title$(input$)\nreturn input$\nend function\nrecord Identity\nid: int16\nend record\nrecord Entry combines Identity\nname: string(8)\nend record\nfile db as Entry = open(\"entries.dat\")\ndb[1] = { id: amount%(1), name: title$(\"ast\") }\ndb[1] = ?{ id: amount%(3) }\nend\n";
        let semantic_source = "program SemanticRecordWrite\nfunction amount%(input%)\nreturn input%\nend function\nfunction title$(input$)\nreturn input$\nend function\nrecord Identity\nid: int16\nend record\nrecord Entry combines Identity\nname: string(8)\nend record\nfile db as Entry = open(\"entries.dat\")\ndb[7] = { id: amount%(22), name: title$(\"typed\") }\ndb[8] = ?{ id: amount%(33) }\nend\n";
        let parsed = parse_source("semantic_record_write.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered {
            program,
            mut lowered_record_files,
            ..
        } = lower::lower(parsed).unwrap();
        lowered_record_files[0].record_length = 14;
        let mut module =
            crate::semantic_ir::parse_and_adapt_named("semantic_record_write.bcl", semantic_source)
                .unwrap();
        module.lowered_record_files = lowered_record_files;
        let resolved = resolver::resolve_with_semantic(program, Some(module)).unwrap();
        let output = generate(&resolved, Target::C).unwrap().app;

        assert!(output.contains("bf_i_amount(22)"), "{output}");
        assert!(output.contains("bf_s_title"), "{output}");
        assert!(output.contains("\"typed\""), "{output}");
        assert!(output.contains("bf_i_amount(33)"), "{output}");
        assert!(output.contains("unsigned char buffer[14]"), "{output}");
        assert!(output.contains("bcc_write_record(file, buffer, 14, record)"), "{output}");
        assert!(
            output.contains("bcc_put_record_entry(bcc_files[0], 7,"),
            "{output}"
        );
        assert!(
            output.contains("bcc_put_record_entry(bcc_files[0], 8,"),
            "{output}"
        );
        assert!(!output.contains("bf_i_amount(1)"), "{output}");
        assert!(!output.contains("bf_i_amount(3)"), "{output}");
        assert!(!output.contains("\"ast\""), "{output}");
        assert!(!output.contains("\"ast\""), "{output}");
    }

