    #[test]
    fn c_record_file_write_consumes_typed_semantic_record_variable_fields() {
        let ast_source = "program SemanticRecordVariableWrite\nfunction slot%(value% = 1)\nreturn value%\nend function\nfunction byrefSlot%(byref value%)\nreturn value%\nend function\nfunction realSlot#(value#)\nreturn value#\nend function\nfunction singleSlot!(value!)\nreturn value!\nend function\nrecord Identity\nid: int16\nserial: int32\nend record\nrecord Entry combines Identity\nratio: float32\nscale: float64\nname: string(8)\nend record\nfile db as Entry = open(\"entries.dat\")\nlet row = { id: 1, serial: 2, ratio: 1.5, scale: 2.5, name: \"ast\" }\nrow.id = 2\nrow.serial = 3\nrow.ratio = 3.5\nrow.scale = 4.5\nrow.name = \"old\"\nlet position% = 1\nlet nextPosition% = 2\ndim positions%(1,1)\npositions%(1,1) = 2\ndb[slot%(1)] = row\ndb[nextPosition%] = (row)\ndb[byrefSlot%(position%)] = row\ndb[realSlot#(1.0)] = row\ndb[singleSlot!(1.0)] = row\nend\n";
        let semantic_source = "program SemanticRecordVariableWrite\nfunction slot%(value% = 7)\nreturn value%\nend function\nfunction byrefSlot%(byref value%)\nreturn value%\nend function\nfunction realSlot#(value#)\nreturn value#\nend function\nfunction singleSlot!(value!)\nreturn value!\nend function\nrecord Identity\nid: int16\nserial: int32\nend record\nrecord Entry combines Identity\nratio: float32\nscale: float64\nname: string(8)\nend record\nfile db as Entry = open(\"entries.dat\")\nlet row = { id: 1, serial: 2, ratio: 1.5, scale: 2.5, name: \"ast\" }\nrow.id = 22\nrow.serial = 33\nrow.ratio = 33.5\nrow.scale = 44.5\nrow.name = \"typed\"\nlet position% = 7\nlet nextPosition% = 8\ndim positions%(1,1)\npositions%(1,1) = 8\ndb[slot%()] = row\ndb[positions%(1,1)] = (row)\ndb[byrefSlot%(nextPosition%)] = row\ndb[realSlot#(7.5)] = row\ndb[singleSlot!(7.5)] = row\nend\n";
        let parsed =
            parse_source("semantic_record_variable_write.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered {
            program,
            lowered_record_files,
            ..
        } = lower::lower(parsed).unwrap();
        let mut module = crate::semantic_ir::parse_and_adapt_named(
            "semantic_record_variable_write.bcl",
            semantic_source,
        )
        .unwrap();
        module.lowered_record_files = lowered_record_files;
        let resolved = resolver::resolve_with_semantic(program, Some(module)).unwrap();
        let output = generate(&resolved, Target::C).unwrap().app;

        assert!(output.contains("bv_i_rowid = 22;"), "{output}");
        assert!(output.contains("bv_l_rowserial = 33;"), "{output}");
        assert!(output.contains("bv_f_rowratio = 33.5;"), "{output}");
        assert!(output.contains("bv_d_rowscale = 44.5;"), "{output}");
        assert!(output.contains("\"typed\""), "{output}");
        assert!(
            output.contains("bcc_put_record_entry(bcc_files[0], bf_i_slot(7),"),
            "{output}"
        );
        assert!(
            output.contains("bf_i_byrefslot(&bv_i_nextposition)"),
            "{output}"
        );
        assert!(output.contains("bf_d_realslot(7.5)"), "{output}");
        assert!(output.contains("bf_f_singleslot(7.5)"), "{output}");
        assert!(
            output.contains("((int)round((double)(bf_d_realslot(7.5))))"),
            "{output}"
        );
        assert!(
            output.contains("((int)round((double)(bf_f_singleslot(7.5))))"),
            "{output}"
        );
        assert!(
            output.contains("bcc_put_record_entry(bcc_files[0], bv_i_positions[(1)][(1)],"),
            "{output}"
        );
        assert!(
            !output.contains("bcc_put_record_entry(bcc_files[0], 1,"),
            "{output}"
        );
        assert!(
            !output.contains("bcc_put_record_entry(bcc_files[0], 2,"),
            "{output}"
        );
        assert!(!output.contains("bv_i_rowid = 2;"), "{output}");
        assert!(!output.contains("bv_l_rowserial = 3;"), "{output}");
        assert!(!output.contains("bv_f_rowratio = 3.5;"), "{output}");
        assert!(!output.contains("bv_d_rowscale = 4.5;"), "{output}");
        assert!(!output.contains("\"old\""), "{output}");
    }

