    #[test]
    fn c_callable_generation_dispatches_semantic_screen_and_randomize_nodes() {
        let ast_source = "function value%(input%)\nreturn input%\nend function\nfunction f%()\nlocate value%(1), value%(2)\ncolor value%(3), value%(4)\nrandomize value%(5)\nreturn 0\nend function\nprint f%()\nend\n";
        let semantic_source = "function value%(input%)\nreturn input%\nend function\nfunction f%()\nlocate value%(77), value%(88)\ncolor value%(33), value%(44)\nrandomize value%(66)\nreturn 0\nend function\nprint f%()\nend\n";
        let program =
            parse_source("c_callable_semantic_screen.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(program).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c_callable_semantic_screen.bcl",
                semantic_source,
            )
            .unwrap(),
        );
        let output = generate(&resolved, Target::C).unwrap().app;
        assert!(
            output.contains("printf(\"\\x1b[%d;%dH\", bf_i_value(77), bf_i_value(88));"),
            "semantic callable LOCATE missing: {output}"
        );
        assert!(
            output.contains("bcc_color(bf_i_value(33), bf_i_value(44));"),
            "semantic callable COLOR missing: {output}"
        );
        assert!(
            output.contains("srand((unsigned int)(bf_i_value(66)));"),
            "semantic callable RANDOMIZE missing: {output}"
        );
        assert!(
            !output.contains("bf_i_value(1)"),
            "AST callable LOCATE arguments replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("bf_i_value(3)"),
            "AST callable COLOR arguments replaced semantic IR: {output}"
        );
        assert!(
            !output.contains("bf_i_value(5)"),
            "AST callable RANDOMIZE argument replaced semantic IR: {output}"
        );
    }

    #[test]
    fn c_callable_arity_and_parameter_names_come_from_semantic_signature() {
        let ast_source =
            "function total%(old%)\nreturn old%\nend function\nresult%=total%(1)\nend\n";
        let semantic_source = "function total%(left%, right%)\nreturn left%+right%\nend function\nresult%=total%(4,5)\nend\n";
        let parsed = parse_source("c_semantic_callable_arity.bcl".to_string(), ast_source).unwrap();
        let lower::Lowered { program, .. } = lower::lower(parsed).unwrap();
        let mut resolved = resolver::resolve(program).unwrap();
        resolved.semantic_module = Some(
            crate::semantic_ir::parse_and_adapt_named(
                "c_semantic_callable_arity.bcl",
                semantic_source,
            )
            .unwrap(),
        );

        let output = generate(&resolved, Target::C).unwrap().app;

        assert!(
            output.contains("int bf_i_total(int bv_i_left, int bv_i_right)"),
            "C prototype must consume typed parameter count and names: {output}"
        );
        assert!(
            output.contains("return (bv_i_left + bv_i_right);"),
            "C callable body must bind typed parameter names: {output}"
        );
        assert!(
            output.contains("bv_i_result = bf_i_total(4, 5);"),
            "C call and function descriptor must use typed callable arity: {output}"
        );
        assert!(
            !output.contains("bv_i_old"),
            "stale AST parameter must not leak into C output: {output}"
        );
    }

