    #[test]
    fn target_c64_uses_semantic_top_level_const_type_for_global_references() {
        let source = "program p\nconst count = 11\nprocedure worker()\nglobal count\nprint count\nend procedure\nworker()\nend\n";
        let parsed = parse_source("semantic_c64_const_type.bcl".to_string(), source)
            .expect("legacy source parses");
        let lower::Lowered { program, .. } = lower::lower(parsed).expect("legacy source lowers");
        let semantic =
            crate::semantic_ir::parse_and_adapt_named("semantic_c64_const_type.bcl", source)
                .expect("typed source parses");
        let resolved = resolver::resolve_with_semantic(program, Some(semantic))
            .expect("semantic constant resolves");

        let output = generate(&resolved, Target::C64).unwrap_or_else(|diagnostics| {
            panic!("typed integer CONST was rejected through GLOBAL: {diagnostics:?}")
        });
        assert!(
            !output.app.contains("bv_f_count"),
            "C64 retained stale floating storage for an integer CONST: {}",
            output.app
        );

        let float_source = source.replace("= 11", "= 11.5");
        let parsed = parse_source(
            "semantic_c64_float_const_type.bcl".to_string(),
            &float_source,
        )
        .expect("floating constant source parses");
        let lower::Lowered { program, .. } =
            lower::lower(parsed).expect("floating constant source lowers");
        let semantic = crate::semantic_ir::parse_and_adapt_named(
            "semantic_c64_float_const_type.bcl",
            &float_source,
        )
        .expect("floating constant typed IR parses");
        let resolved = resolver::resolve_with_semantic(program, Some(semantic))
            .expect("floating constant resolves");
        let diagnostics = match generate(&resolved, Target::C64) {
            Ok(_) => panic!("typed floating CONST must be rejected by C64"),
            Err(diagnostics) => diagnostics,
        };
        assert!(
            diagnostics.iter().any(|diagnostic| {
                diagnostic.message.contains("C64 (cc65)") && diagnostic.message.contains("count")
            }),
            "typed floating CONST diagnostic missing: {diagnostics:?}"
        );
    }

