        let semantic_source = "program p\ndim index as long\nfor index = 1 to 4\nselect case index\ncase 1\nprint \"typed one\"\ncontinue\ncase 2 to 3\nprint \"typed range\"\ncase is > 3\nprint \"typed compare\"\ncase else\nprint \"typed else\"\nend select\nend for\nend\n";
