    #[test]
    fn target_c64_dispatches_top_level_select_case_from_semantic_ir() {
        let ast_source = "program p\ndim choice\nchoice = 1\nselect case choice\ncase 1\nprint \"AST one\"\ncase 2 to 3\nprint \"AST range\"\ncase is > 3\nprint \"AST compare\"\ncase else\nprint \"AST else\"\nend select\nend\n";
        let semantic_source = "program p\ndim choice as long\nchoice = 7\nselect case choice\ncase 7\nprint \"typed one\"\ncase 8 to 9\nprint \"typed range\"\ncase is > 9\nprint \"typed compare\"\ncase else\nprint \"typed else\"\nend select\nend\n";
        let parsed = parse_source("semantic_c64_top_level_select.bcl".to_string(), ast_source)
            .expect("legacy source parses");
        let lower::Lowered { program, .. } = lower::lower(parsed).expect("source lowers");
        let semantic = crate::semantic_ir::parse_and_adapt_named(
            "semantic_c64_top_level_select.bcl",
            semantic_source,
        )
        .expect("typed source parses");
        let resolved = resolver::resolve_with_semantic(program, Some(semantic))
            .expect("typed SELECT CASE resolves");
        let output = generate(&resolved, Target::C64)
            .unwrap_or_else(|diagnostics| {
                panic!("typed top-level SELECT CASE was rejected: {diagnostics:?}")
            })
            .app;
        assert!(output.contains("int bt_sel_"), "{output}");
        assert!(
            output.contains("(bt_sel_0 == 7)"),
            "typed CASE value missing: {output}"
        );
        assert!(
            output.contains("(bt_sel_0 >= 8 && bt_sel_0 <= 9)"),
            "typed CASE range missing: {output}"
        );
        assert!(
            output.contains("(bt_sel_0 > 9)"),
            "typed CASE comparison missing: {output}"
        );
        assert!(output.contains("typed one"), "{output}");
        assert!(output.contains("typed range"), "{output}");
        assert!(output.contains("typed compare"), "{output}");
        assert!(output.contains("typed else"), "{output}");
        for stale in ["AST one", "AST range", "AST compare", "AST else"] {
            assert!(
                !output.contains(stale),
                "stale AST text `{stale}` leaked: {output}"
            );
        }
    }

