    #[test]
    fn c_callable_dispatches_string_select_case_from_semantic_ir() {
        let ast_source = "program p\nprocedure worker()\ndim choice$\nchoice$ = \"old\"\nselect case choice$\ncase \"old\"\nprint \"AST callable string\"\ncase else\nprint \"AST callable else\"\nend select\nend procedure\nworker()\nend\n";
        let semantic_source = "program p\nprocedure worker()\ndim choice$\nchoice$ = \"typed\"\nselect case choice$\ncase \"typed\"\nprint \"typed callable string\"\ncase else\nprint \"typed callable else\"\nend select\nend procedure\nworker()\nend\n";
        let parsed = parse_source(
            "semantic_callable_string_select.bcl".to_string(),
            ast_source,
        )
        .expect("legacy callable source parses");
        let lower::Lowered { program, .. } = lower::lower(parsed).expect("source lowers");
        let semantic = crate::semantic_ir::parse_and_adapt_named(
            "semantic_callable_string_select.bcl",
            semantic_source,
        )
        .expect("typed callable source parses");
        let resolved = resolver::resolve_with_semantic(program, Some(semantic))
            .expect("typed callable string selection resolves");
        let output = generate(&resolved, Target::C64)
            .unwrap_or_else(|diagnostics| {
                panic!("typed callable string SELECT was rejected: {diagnostics:?}")
            })
            .app;
        assert!(output.contains("#include <string.h>"), "{output}");
        assert!(output.contains("strcmp(bt_sel_"), "{output}");
        assert!(output.contains("typed callable string"), "{output}");
        assert!(output.contains("typed callable else"), "{output}");
        assert!(!output.contains("old"), "stale AST string leaked: {output}");
        assert!(!output.contains("AST callable string"), "{output}");
        assert!(!output.contains("AST callable else"), "{output}");
    }

    #[test]
    fn target_c64_dispatches_root_if_and_while_from_semantic_ir() {
        let ast_source = "program p\ndim index\nindex = 0\nwhile index < 2\nindex += 1\nif index = 1 then\nprint \"AST branch\"\nelse\nprint \"AST alternative\"\nend if\ncontinue\nend while\nif index = 2 then\nprint \"AST final\"\nelse\nprint \"AST final else\"\nend if\nend\n";
        let semantic_source = "program p\ndim index as long\nindex = 0\nwhile index < 3\nindex += 1\nif index = 2 then\nprint \"typed branch\"\nelse\nprint \"typed alternative\"\nend if\ncontinue\nend while\nif index = 3 then\nprint \"typed final\"\nelse\nprint \"typed final else\"\nend if\nend\n";
        let parsed = parse_source("semantic_c64_root_if_while.bcl".to_string(), ast_source)
            .expect("legacy source parses");
        let lower::Lowered { program, .. } = lower::lower(parsed).expect("source lowers");
        let semantic = crate::semantic_ir::parse_and_adapt_named(
            "semantic_c64_root_if_while.bcl",
            semantic_source,
        )
        .expect("typed source parses");
        let resolved = resolver::resolve_with_semantic(program, Some(semantic))
            .expect("typed IF and WHILE resolve");
        let output = generate(&resolved, Target::C64)
            .unwrap_or_else(|diagnostics| {
                panic!("typed top-level IF/WHILE was rejected: {diagnostics:?}")
            })
            .app;
        assert!(output.contains("int bv_l_index = 0;"), "{output}");
        assert!(output.contains("typed branch"), "{output}");
        assert!(output.contains("typed alternative"), "{output}");
        assert!(output.contains("typed final"), "{output}");
        assert!(output.contains("typed final else"), "{output}");
        assert!(output.contains("continue;"), "{output}");
        for stale in ["AST branch", "AST alternative", "AST final"] {
            assert!(!output.contains(stale), "stale `{stale}` leaked: {output}");
        }
        assert!(!output.contains("bv_f_index"), "{output}");
    }

