        let ast_source = "program p\nprocedure worker()\ndim index\ndo while index < 10\nindex += 1\ncontinue\nprint \"AST callable loop\"\nloop until index >= 2\nend procedure\nworker()\nend\n";
        let semantic_source = "program p\nprocedure worker()\ndim index as long\ndo while index < 10\nindex += 1\ncontinue\nprint \"typed callable loop\"\nloop until index >= 3\nend procedure\nworker()\nend\n";
