    #[test]
    fn target_c64_ignores_ast_only_float_assignment_when_semantic_statement_replaces_it() {
        let ast_source = "program p\nobsolete# = 1\nend\n";
        let semantic_source = "program p\ncurrent% = 2\nend\n";
        let parsed = parse_source("semantic_c64_replaced_float.bcl".to_string(), ast_source)
            .expect("legacy source parses");
        let lower::Lowered { program, .. } = lower::lower(parsed).expect("legacy source lowers");
        let semantic = crate::semantic_ir::parse_and_adapt_named(
            "semantic_c64_replaced_float.bcl",
            semantic_source,
        )
        .expect("typed source parses");
        let resolved = resolver::resolve_with_semantic(program, Some(semantic))
            .expect("semantic replacement resolves");

        let output = generate(&resolved, Target::C64)
            .unwrap_or_else(|diagnostics| {
                panic!(
                    "AST-only float assignment leaked into C64 capability checks: {diagnostics:?}"
                )
            })
            .app;
        assert!(output.contains("bv_i_current = 2;"), "{output}");
        assert!(
            !output.contains("obsolete"),
            "AST-only binding leaked: {output}"
        );

        let parsed = parse_source(
            "semantic_c64_float_read.bcl".to_string(),
            "program p\nprint value&\nend\n",
        )
        .expect("legacy source parses");
        let lower::Lowered { program, .. } = lower::lower(parsed).expect("legacy source lowers");
        let semantic = crate::semantic_ir::parse_and_adapt_named(
            "semantic_c64_float_read.bcl",
            "program p\nprint value#\nend\n",
        )
        .expect("typed source parses");
        let resolved = resolver::resolve_with_semantic(program, Some(semantic))
            .expect("semantic float read resolves");
        let diagnostics = match generate(&resolved, Target::C64) {
            Err(diagnostics) => diagnostics,
            Ok(_) => panic!("typed double read must be rejected"),
        }
        .into_iter()
        .map(|diagnostic| diagnostic.message)
        .collect::<Vec<_>>();
        assert!(diagnostics
            .iter()
            .any(|message| message.contains("floating-point") && message.contains("value")));
    }

